from solution import merge_dict


def test_issue_example_given():
    """Merge {'a': 100, 'b': 200} with {'x': 300, 'y': 200} gives all four entries."""
    result = merge_dict({'a': 100, 'b': 200}, {'x': 300, 'y': 200})
    # hand-computed: 2 + 2 = 4 entries unioned as-is
    assert result == {'a': 100, 'b': 200, 'x': 300, 'y': 200}


def test_issue_both_empty():
    """Merge two dictionaries handles two empty inputs."""
    result = merge_dict({}, {})
    # hand-computed: 0 + 0 = 0 entries
    assert result == {}


def test_issue_first_empty():
    """Merge two dictionaries with first empty returns second entries."""
    result = merge_dict({}, {'x': 300, 'y': 200})
    # hand-computed: 0 + 2 = 2 entries
    assert result == {'x': 300, 'y': 200}


def test_issue_second_empty():
    """Merge two dictionaries with second empty returns first entries."""
    result = merge_dict({'a': 100, 'b': 200}, {})
    # hand-computed: 2 + 0 = 2 entries
    assert result == {'a': 100, 'b': 200}


def test_issue_single_each_disjoint():
    """Merge two dictionaries with one disjoint entry each."""
    result = merge_dict({'a': 1}, {'b': 2})
    # hand-computed: 1 + 1 = 2 entries
    assert result == {'a': 1, 'b': 2}


def test_issue_many_disjoint():
    """Merge two dictionaries with several disjoint entries."""
    result = merge_dict({'a': 1, 'b': 2, 'c': 3}, {'x': 4, 'y': 5, 'z': 6})
    # hand-computed: 3 + 3 = 6 entries
    assert result == {'a': 1, 'b': 2, 'c': 3, 'x': 4, 'y': 5, 'z': 6}


def test_issue_int_keys_disjoint():
    """Merge two dictionaries works with non-string keys."""
    result = merge_dict({1: 100}, {2: 200})
    # hand-computed: 1 + 1 = 2 entries with values 100 and 200
    assert result == {1: 100, 2: 200}


def test_issue_mixed_value_types():
    """Merge two dictionaries preserves values of different types."""
    result = merge_dict({'a': None}, {'b': [1, 2]})
    # hand-computed: 1 + 1 = 2 entries, values None and [1, 2]
    assert result == {'a': None, 'b': [1, 2]}


def test_issue_nested_values():
    """Merge two dictionaries preserves nested dict values."""
    result = merge_dict({'a': {'x': 1}}, {'b': {'y': 2}})
    # hand-computed: 1 + 1 = 2 entries with nested values
    assert result == {'a': {'x': 1}, 'b': {'y': 2}}


def test_issue_overlapping_keys_union():
    """Merge two dictionaries keeps every key when keys overlap."""
    result = merge_dict({'a': 1, 'b': 2}, {'b': 20, 'c': 3})
    # hand-computed: union is 2 + 2 - 1 = 3 keys; b is 2 or 20
    assert set(result.keys()) == {'a', 'b', 'c'} and result['a'] == 1 and result['c'] == 3 and result['b'] in (2, 20)


def test_contract_returns_dict():
    """Write a function to merge two dictionaries returns a dict."""
    result = merge_dict({'a': 100}, {'b': 200})
    # hand-computed: 1 + 1 = 2 entries, type is dict
    assert isinstance(result, dict) and result == {'a': 100, 'b': 200}


def test_contract_length_is_sum_when_disjoint():
    """Merge two dictionaries result length is sum of inputs when disjoint."""
    result = merge_dict({'a': 100, 'b': 200}, {'x': 300})
    # hand-computed length: 2 + 1 = 3
    assert len(result) == 3
